for _l, _kv in ROLL.items():
    T[_l].update(_kv)

DIRS = {"en": "values", "pt": "values-pt", "es": "values-es", "fr": "values-fr", "de": "values-de",
        "tr": "values-tr", "in": "values-in", "hi": "values-hi"}


def esc(v):
    return v.replace("\\", "\\\\").replace("'", "\\'").replace("&", "&amp;").replace("<", "&lt;")


keys = list(T["en"].keys())
for lang, kv in T.items():
    missing = [k for k in keys if k not in kv]
    extra = [k for k in kv if k not in keys]
    assert not missing and not extra, (lang, missing, extra)
    for k in keys:
        assert sorted(re.findall(r"%\d\$\d*d", kv[k])) == sorted(re.findall(r"%\d\$\d*d", T["en"][k])), (lang, k)
    d = os.path.join(RES, DIRS[lang])
    os.makedirs(d, exist_ok=True)
    body = ""
    if lang == "en":
        body += '    <string name="app_name">Prisma Roll</string>\n'
    body += "".join(f'    <string name="{k}">{esc(kv[k])}</string>\n' for k in keys)
    with open(os.path.join(d, "strings.xml"), "w") as f:
        f.write('<?xml version="1.0" encoding="utf-8"?>\n<resources>\n' + body + "</resources>\n")
print("ok", len(keys), "keys x", len(T), "languages")
